body.script:
    "use strict";

    /**
     * SafelinkDecryptor - Handles URL decryption and display
     */
    class SafelinkDecryptor {
      constructor(config) {
        this.config = config;
      }

      decryptUrl(encryptedUrl, password) {
        try {
          const decrypted = CryptoJS.AES.decrypt(
            decodeURIComponent(encryptedUrl),
            password
          ).toString(CryptoJS.enc.Utf8);
          return JSON.parse(decrypted);
        } catch (e) {
          return false;
        }
      }

      getUrlParameter(name, url) {
        if (!url) url = location.href;
        name = name.replace(/[\[]/, "\\[").replace(/[\]]/, "\\]");
        const regex = new RegExp("[\\?&]" + name + "=([^&#]*)");
        const results = regex.exec(url);
        return results === null ? null : decodeURIComponent(results[1]);
      }

      renderLink(data) {
        const baseUrl = data.url.toLowerCase().startsWith('www.') ? '\/\/' : '';
        return `
           ${this.config.lang.gourltext}
        `;
      }

      renderCountdown(data, container) {
        let timeLeft = this.config.timedown;
        const baseUrl = data.url.toLowerCase().startsWith('www.') ? '\/\/' : '';

        const countdownInterval = setInterval(() => {
          const text = this.config.lang.countdowntext.replace('{{anascountdown}}', timeLeft);
          container.innerHTML = `
${text}`;
          timeLeft--;

          if (timeLeft < 0) {
            clearInterval(countdownInterval);
            container.innerHTML = this.renderLink(data);
          }
        }, 1000);
      }
    }

    /**
     * SafelinkGenerator - Handles URL encryption and generation
     */
    class SafelinkGenerator {
      constructor(config) {
        this.config = config;
        this.init();
      }

      init() {
        document.addEventListener('DOMContentLoaded', () => {
          this.setupEventListeners();
        });
      }

      setupEventListeners() {
        const form = document.getElementById('safelink');
        if (form) {
          form.addEventListener('submit', (e) => this.handleFormSubmit(e));
        }
      }

      validateUrl(url) {
        const urlPattern = /(https?:\/\/(www\.)\?|www\.)[^\s]+\.[^\s]+/i;
        return urlPattern.test(url);
      }

      encryptData(data, password) {
        return encodeURIComponent(
          CryptoJS.AES.encrypt(JSON.stringify(data), password).toString()
        );
      }

      generateSafelink(url, password, countdown) {
        const blogUrl = this.config.url || window.location.origin;
        const keyit = password || this.config.defaultkey;
        const data = {
          url: url,
          countdown: countdown
        };

        const encrypted = this.encryptData(data, keyit);
        return `${blogUrl}/${this.config.page}?u=${encrypted}`;
      }

      handleFormSubmit(e) {
        e.preventDefault();

        const urlInput = document.getElementById('urlinput');
        const passwordInput = document.getElementById('passinput');
        const countdownCheck = document.getElementById('countDown');
        const resultDiv = document.getElementById('result');

        if (!this.validateUrl(urlInput.value)) {
          resultDiv.innerHTML = `

             ${this.config.lang.validtext}

          `;
          resultDiv.style.display = 'block';
          return;
        }

        const safelink = this.generateSafelink(
          urlInput.value,
          passwordInput.value,
          countdownCheck.checked
        );

        resultDiv.innerHTML = `


             ${this.config.lang.convertsuccess}






               Kopjo


        `;
        resultDiv.style.display = 'block';
      }
    }

    /**
     * ThemeManager - Handles dark mode toggle
     */
    class ThemeManager {
      constructor() {
        this.darkMode = localStorage.getItem('darkMode') === 'true';
        this.init();
      }

      init() {
        this.applyTheme();
        const toggle = document.getElementById('themeToggle');
        if (toggle) {
          toggle.addEventListener('click', () => this.toggleTheme());
        }
      }

      toggleTheme() {
        this.darkMode = !this.darkMode;
        localStorage.setItem('darkMode', this.darkMode);
        this.applyTheme();
      }

      applyTheme() {
        if (this.darkMode) {
          document.body.classList.add('dark-mode');
          const toggle = document.getElementById('themeToggle');
          if (toggle) toggle.innerHTML = '';
        } else {
          document.body.classList.remove('dark-mode');
          const toggle = document.getElementById('themeToggle');
          if (toggle) toggle.innerHTML = '';
        }
      }
    }

    // Initialize
    window.asli_config = {
      url: '',
      page: 'p/safelink.html',
      output: '#output',
      defaultkey: 'NihLink2024',
      fixednavbar: true,
      countdown: true,
      timedown: 10,
      analytics: true,
      lang: {
        urlempty: "URL mund të mos jetë e zbrazët",
        convertsuccess: "Konvertimi i URL-it ishte i suksesshëm, kopjoni URL-in më poshtë",
        validtext: "HTTP, HTTPS, ose WWW",
        gourltext: "Kliko këtu për të shkuar",
        nourl: "Nuk ka URL këtu",
        errorconvert: "URL nuk mund të konvertohet",
        emptypass: "Fjalekalimi nuk mund të jetë i zbrazët",
        wrongpass: "Fjalekalimi është i pasaktë",
        countdowntext: "Ju lutemi prisni {{anascountdown}} sekonda"
      }
    };

    document.addEventListener('DOMContentLoaded', () => {
      window.config = Object.assign({}, window.asli_config);
      new SafelinkGenerator(window.config);
      new ThemeManager();

      // Handle decryption on single item page
      if (document.body.classList.contains('single-item')) {
        const decryptor = new SafelinkDecryptor(window.config);
        const encryptedUrl = decryptor.getUrlParameter('u');
        const outputContainer = document.querySelector(window.config.output);

        if (encryptedUrl && outputContainer) {
          const data = decryptor.decryptUrl(encryptedUrl, window.config.defaultkey);
          if (data) {
            if (!data.countdown) {
              outputContainer.innerHTML = decryptor.renderLink(data);
            } else {
              decryptor.renderCountdown(data, outputContainer);
            }
          }
        }
      }
    });
